// spec: specs/seo-robots-sitemap.md — общее: разбор robots.txt (правила Google), чтение sitemap. Прод, только GET.
import { expect, type APIRequestContext } from '@playwright/test';

export const ORIGIN = 'https://www.biz4sale.co.il';

export const BOTS = ['*', 'Googlebot', 'Bingbot', 'Google-Extended', 'GPTBot', 'ClaudeBot', 'PerplexityBot'];

/** 20 закрытых путей (AC3 #d777c9, מצב רצוי реджекта rej_0effd95e). */
export const BLOCKED_PATHS = [
  '/admin', '/api/', '/qa/', '/auth-test', '/payment/',
  '/auth', '/complete-profile', '/userprofile', '/changepassword', '/usernotifications', '/userpackages',
  '/messages', '/favoritesandconversations', '/savedsearches', '/mybusinesses',
  '/addbusiness', '/postbuyerrequest', '/publishconfirmation', '/businessresultempty', '/mapview',
];

type Rule = { allow: boolean; path: string };
type Group = { agents: string[]; rules: Rule[] };
export type Robots = { text: string; groups: Group[]; sitemaps: string[] };

export function parseRobots(text: string): Robots {
  const groups: Group[] = [];
  const sitemaps: string[] = [];
  let cur: Group | null = null;
  let lastWasAgent = false;
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.replace(/#.*$/, '').trim();
    if (!line) continue;
    const i = line.indexOf(':');
    if (i < 0) continue;
    const key = line.slice(0, i).trim().toLowerCase();
    const val = line.slice(i + 1).trim();
    if (key === 'user-agent') {
      if (!cur || !lastWasAgent) { cur = { agents: [], rules: [] }; groups.push(cur); }
      cur.agents.push(val.toLowerCase());
      lastWasAgent = true;
    } else if (key === 'allow' || key === 'disallow') {
      lastWasAgent = false;
      if (cur && val) cur.rules.push({ allow: key === 'allow', path: val });
    } else if (key === 'sitemap') {
      sitemaps.push(val);
    } else {
      lastWasAgent = false;
    }
  }
  return { text, groups, sitemaps };
}

/** Группа бота: где назван его токен, иначе «*». */
function groupFor(r: Robots, bot: string): Group[] {
  const b = bot.toLowerCase();
  if (b !== '*') {
    const named = r.groups.filter((g) => g.agents.includes(b));
    if (named.length) return named;
  }
  return r.groups.filter((g) => g.agents.includes('*'));
}

function ruleRegex(p: string): RegExp {
  const end = p.endsWith('$');
  const body = (end ? p.slice(0, -1) : p).split('*').map((s) => s.replace(/[.+?^${}()|[\]\\]/g, '\\$&')).join('.*');
  return new RegExp('^' + body + (end ? '$' : ''));
}

/** Разрешён ли путь (pathname + search) боту: самое длинное совпадение, при равенстве — Allow. */
export function isAllowed(r: Robots, bot: string, path: string): boolean {
  let best: Rule | null = null;
  for (const g of groupFor(r, bot)) {
    for (const rule of g.rules) {
      if (!ruleRegex(rule.path).test(path)) continue;
      if (!best || rule.path.length > best.path.length || (rule.path.length === best.path.length && rule.allow)) best = rule;
    }
  }
  return best ? best.allow : true;
}

export async function readRobots(request: APIRequestContext) {
  const res = await request.get('/robots.txt');
  expect(res.status(), '/robots.txt статус').toBe(200);
  const ctype = res.headers()['content-type'] ?? '';
  return { ctype, robots: parseRobots(await res.text()) };
}

export function decodeEntities(s: string): string {
  return s
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(parseInt(d, 10)))
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&');
}

export async function readSitemap(request: APIRequestContext) {
  const res = await request.get('/sitemap.xml');
  expect(res.status(), '/sitemap.xml статус').toBe(200);
  const body = await res.text();
  const locs = [...body.matchAll(/<loc>\s*([^<]+?)\s*<\/loc>/gi)].map((m) => decodeEntities(m[1]));
  const listingIds = [
    ...new Set(
      locs
        .map((l) => new URL(l))
        .filter((u) => u.pathname === '/businessdetail' && u.searchParams.get('id'))
        .map((u) => u.searchParams.get('id')!),
    ),
  ];
  return { ctype: res.headers()['content-type'] ?? '', body, locs, listingIds };
}

/** content всех <meta name="robots">. */
export function robotsMeta(html: string): string[] {
  const out: string[] = [];
  for (const tag of html.match(/<meta\b[^>]*>/gi) ?? []) {
    if (!/\bname\s*=\s*["']robots["']/i.test(tag)) continue;
    const m = tag.match(/\bcontent\s*=\s*"([^"]*)"|\bcontent\s*=\s*'([^']*)'/i);
    if (m) out.push(decodeEntities(m[1] ?? m[2]).trim());
  }
  return out;
}

/** meta robots «index» без «noindex». */
export const indexMeta = (meta: string[]) => meta.some((m) => !/noindex/i.test(m) && /(^|[,\s])index\b/i.test(m));
